import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Button,
  Input,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type {
  TrialBalanceChessboardColumn,
  TrialBalanceChessboardRow,
} from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel, monthStartEnd } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { navigateInAppPath } from '../../../router/navigateInAppPath';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './CanDoiPhatSinhBanCoPage.module.css';

const TEST_ID = 'rpt-can-doi-phat-sinh-ban-co';
const PAGE_ID = 'baocao-can-doi-phat-sinh-ban-co';
const TITLE = 'Bảng cân đối phát sinh (Bàn cờ)';

type RowTag = 'Leaf' | 'Parent' | 'Total' | 'Blank';

const FIXED_COLUMNS: TrialBalanceChessboardColumn[] = [
  { key: 'debitAccountCodeDisplay', kind: 'fixed', headerVi: 'Tk Nợ', headerEn: 'Debit Acc' },
  { key: 'debitAccountName', kind: 'fixed', headerVi: 'Tên tài khoản', headerEn: 'Debit Acc Name' },
  { key: 'periodTotal', kind: 'fixed', headerVi: 'Tổng phát sinh', headerEn: 'Total' },
];

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function mapRowTag(
  raw: TrialBalanceChessboardRow['rowTag'],
  isTotal?: boolean,
  isParent?: boolean,
): RowTag {
  if (raw === 'Blank') return 'Blank';
  if (raw === 'Total' || isTotal) return 'Total';
  if (raw === 'Parent' || isParent) return 'Parent';
  return 'Leaf';
}

function normalizeItems(items: TrialBalanceChessboardRow[]): TrialBalanceChessboardRow[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag, r.isTotal, r.isParent);
    const isTotal = rowTag === 'Total' || Boolean(r.isTotal);
    const isParent = rowTag === 'Parent' || Boolean(r.isParent);
    const isBlank = rowTag === 'Blank';
    return {
      ...r,
      rowTag,
      isTotal,
      isParent,
      isBold: isBlank ? false : Boolean(r.isBold) || isTotal || isParent,
      debitAccountCode: r.debitAccountCode ?? '',
      debitAccountCodeDisplay: r.debitAccountCodeDisplay ?? '',
      debitAccountName: r.debitAccountName ?? '',
      accountLevel: Number(r.accountLevel ?? 0),
      periodTotal: Number(r.periodTotal ?? 0),
      creditAmounts: r.creditAmounts ?? {},
    };
  });
}

function rowClass(tag: RowTag): string {
  if (tag === 'Total') return styles.rowToneTotal;
  if (tag === 'Blank') return styles.rowToneBlank;
  if (tag === 'Parent') return `${styles.rowToneParent} ${styles.rowDrillable}`;
  return `${styles.rowToneLeaf} ${styles.rowDrillable}`;
}

function moneyCell(tag: RowTag, value: number): string {
  if (tag === 'Blank') return '';
  return formatVnd(value);
}

function creditCodeOf(col: TrialBalanceChessboardColumn): string {
  if (col.creditAccountCode) return col.creditAccountCode;
  if (col.key?.startsWith('C')) return col.key.slice(1);
  return '';
}

const CanDoiPhatSinhBanCoPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const initial = monthStartEnd();

  const [fromDate, setFromDate] = useState(initial.fromDate);
  const [toDate, setToDate] = useState(initial.toDate);
  const [columns, setColumns] = useState<TrialBalanceChessboardColumn[]>(FIXED_COLUMNS);
  const [items, setItems] = useState<TrialBalanceChessboardRow[]>([]);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const [contextMenu, setContextMenu] = useState<{
    x: number;
    y: number;
    row: TrialBalanceChessboardRow;
  } | null>(null);
  const { showTableLoading } = useCatalogTableBusy(loading);

  const displayColumns = hasViewed && columns.length > 0 ? columns : FIXED_COLUMNS;
  const creditColumns = useMemo(
    () => displayColumns.filter(c => c.kind === 'credit' || Boolean(c.creditAccountCode)),
    [displayColumns],
  );

  const summaryPeriodTotal = useMemo(() => {
    if (!hasViewed) return null;
    const total = items.find(r => mapRowTag(r.rowTag, r.isTotal, r.isParent) === 'Total');
    return total ? Number(total.periodTotal ?? 0) : null;
  }, [hasViewed, items]);

  const leafCount = useMemo(
    () => items.filter(r => mapRowTag(r.rowTag, r.isTotal, r.isParent) === 'Leaf').length,
    [items],
  );

  useEffect(() => {
    if (!contextMenu) return undefined;
    const close = () => setContextMenu(null);
    window.addEventListener('click', close);
    return () => window.removeEventListener('click', close);
  }, [contextMenu]);

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    if (!fromDate.trim() || !toDate.trim()) {
      setFilterError('Chọn khoảng ngày');
      dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
      return;
    }
    if (toDate < fromDate) {
      setFilterError('Đến ngày phải ≥ Từ ngày');
      dispatchAppToast(dispatch, { message: 'Đến ngày phải ≥ Từ ngày', type: 'error' });
      return;
    }

    setLoading(true);
    analyticsService
      .getTrialBalanceChessboard({
        fromDate: fromDate.trim(),
        toDate: toDate.trim(),
        pageSize: 0,
      })
      .then(report => {
        const nextCols =
          Array.isArray(report.columns) && report.columns.length > 0
            ? report.columns
            : FIXED_COLUMNS;
        setColumns(nextCols);
        setItems(normalizeItems(report.items ?? []));
        setAppliedFrom(fromDate.trim());
        setAppliedTo(toDate.trim());
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được bảng cân đối phát sinh (bàn cờ)'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [dispatch, fromDate, toDate]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    const next = monthStartEnd();
    setFromDate(next.fromDate);
    setToDate(next.toDate);
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading || !appliedFrom || !appliedTo) return;
    const fileName = `can-doi-phat-sinh-ban-co_${appliedFrom}_${appliedTo}.xlsx`;
    void exportExcel(
      '/accounting/trial-balance-chessboard/export-excel',
      {
        fromDate: appliedFrom,
        toDate: appliedTo,
        pageSize: 0,
      },
      fileName,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedFrom, appliedTo, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  const drillToBangKe = useCallback(
    (row: TrialBalanceChessboardRow) => {
      if (!hasViewed) return;
      const tag = mapRowTag(row.rowTag, row.isTotal, row.isParent);
      if (tag === 'Total') {
        dispatchAppToast(dispatch, {
          message: 'Không mở chi tiết từ hàng tổng',
          type: 'info',
        });
        return;
      }
      if (tag === 'Blank') return;
      const code = (row.debitAccountCode ?? '').trim();
      if (!code || !appliedFrom || !appliedTo) return;
      const qs = new URLSearchParams({
        accountCode: code,
        fromDate: appliedFrom,
        toDate: appliedTo,
        groupBy: 'TK_CO',
      });
      navigateInAppPath(`/baocao/bang-ke-chung-tu?${qs.toString()}`, navigate);
    },
    [appliedFrom, appliedTo, dispatch, hasViewed, navigate],
  );

  const onRowDoubleClick = useCallback(
    (_e: React.MouseEvent, row: TrialBalanceChessboardRow) => {
      drillToBangKe(row);
    },
    [drillToBangKe],
  );

  const onRowContextMenu = useCallback(
    (e: React.MouseEvent, row: TrialBalanceChessboardRow) => {
      const tag = mapRowTag(row.rowTag, row.isTotal, row.isParent);
      if (tag === 'Blank') return;
      if (tag === 'Total') {
        e.preventDefault();
        dispatchAppToast(dispatch, {
          message: 'Không mở chi tiết từ hàng tổng',
          type: 'info',
        });
        return;
      }
      e.preventDefault();
      setContextMenu({ x: e.clientX, y: e.clientY, row });
    },
    [dispatch],
  );

  const exportDisabled = !hasViewed || loading || !appliedFrom;

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: exportDisabled,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [exportDisabled, handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle =
    hasViewed && appliedFrom && appliedTo
      ? `Từ: ${formatDate(appliedFrom)} đến ngày ${formatDate(appliedTo)}`
      : undefined;

  const listBody = showTableLoading ? null : (
    <div className={erp.tableWrapper}>
      {subtitle ? (
        <div data-testid={`${TEST_ID}-subtitle`} className={reportStyles.subtitle} style={{ marginBottom: '0.5rem' }}>
          {subtitle}
        </div>
      ) : null}
      <div className={styles.gridScroll} data-testid={`${TEST_ID}-grid-scroll`}>
        <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
          <thead>
            <tr>
              {displayColumns.map(col => {
                const isCredit = col.kind === 'credit' || Boolean(col.creditAccountCode);
                const code = creditCodeOf(col);
                return (
                  <th
                    key={col.key}
                    className={
                      col.key === 'periodTotal' || isCredit ? reportStyles.colRight : undefined
                    }
                    data-testid={
                      isCredit && code ? `${TEST_ID}-col-credit-${code}` : undefined
                    }
                    data-credit-account={isCredit ? code : undefined}
                  >
                    {col.headerVi ?? col.key}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {!hasViewed
              ? null
              : items.map((row, index) => {
                  const tag = mapRowTag(row.rowTag, row.isTotal, row.isParent);
                  const isTotal = tag === 'Total';
                  const isParent = tag === 'Parent';
                  const isBlank = tag === 'Blank';
                  const drillable = tag === 'Leaf' || tag === 'Parent';
                  return (
                    <tr
                      key={`${tag}|${row.debitAccountCode ?? 'T'}|${isParent ? 'P' : 'L'}|${index}`}
                      className={rowClass(tag)}
                      data-testid={`${TEST_ID}-row-${index}`}
                      data-row-tag={tag}
                      data-is-parent={isParent ? '1' : '0'}
                      data-is-total={isTotal ? '1' : '0'}
                      data-account-code={row.debitAccountCode ?? ''}
                      data-drillable={drillable ? '1' : '0'}
                      title={drillable ? 'Double-click: bảng kê chứng từ' : undefined}
                      onDoubleClick={e => onRowDoubleClick(e, row)}
                      onContextMenu={e => onRowContextMenu(e, row)}
                    >
                      <td className={styles.cellIndent}>
                        {isTotal || isBlank
                          ? ''
                          : (row.debitAccountCodeDisplay ?? row.debitAccountCode ?? '')}
                      </td>
                      <td>{isBlank ? '' : (row.debitAccountName ?? '')}</td>
                      <td className={reportStyles.colRight}>
                        {moneyCell(tag, row.periodTotal ?? 0)}
                      </td>
                      {creditColumns.map(col => {
                        const code = creditCodeOf(col);
                        const amount = Number(row.creditAmounts?.[code] ?? 0);
                        return (
                          <td key={col.key} className={reportStyles.colRight}>
                            {moneyCell(tag, amount)}
                          </td>
                        );
                      })}
                    </tr>
                  );
                })}
          </tbody>
        </table>
      </div>
      {hasViewed && leafCount === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  const footer =
    hasViewed && summaryPeriodTotal !== null ? (
      <div className={styles.summaryBar} data-testid={`${TEST_ID}-summary`}>
        <span>Tổng phát sinh: {formatVnd(summaryPeriodTotal)}</span>
      </div>
    ) : undefined;

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-th' }}
        listTitle={TITLE}
        filterMaxWidthPx={1400}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        footer={footer}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-fromDate`}>
              <Input
                type="date"
                label="Từ ngày"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-from`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toDate`}>
              <Input
                type="date"
                label="Đến ngày"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-to`}
              />
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </>
        )}
      >
        {listBody}
      </LinPageLayout>
      {contextMenu ? (
        <div
          className={styles.contextMenu}
          style={{ left: contextMenu.x, top: contextMenu.y }}
          data-testid={`${TEST_ID}-context-menu`}
          onClick={e => e.stopPropagation()}
        >
          <button
            type="button"
            data-testid={`${TEST_ID}-drill-bang-ke`}
            onClick={() => {
              drillToBangKe(contextMenu.row);
              setContextMenu(null);
            }}
          >
            Bảng kê chứng từ
          </button>
        </div>
      ) : null}
    </div>
  );
};

export default CanDoiPhatSinhBanCoPage;
